Script.script:
aardwolf_map = aardwolf_map or {}
aardwolf_map.settings = aardwolf_map.settings or {}

function aardwolf_map.settings.map_key(name)
  return "aardwolf_map." .. name
end

function aardwolf_map.settings.get_map_value(name)
  return getMapUserData(aardwolf_map.settings.map_key(name))
end

function aardwolf_map.settings.set_map_value(name, value)
  setMapUserData(aardwolf_map.settings.map_key(name), value)
end

function aardwolf_map.settings.get_area_ids()
  local value = aardwolf_map.state.decode_value(aardwolf_map.settings.get_map_value("area_ids"))
  if type(value) == "table" then
    return value
  end
  return {}
end

function aardwolf_map.settings.set_area_ids(area_ids)
  local encoded = aardwolf_map.state.encode_value(area_ids)
  if encoded then
    aardwolf_map.settings.set_map_value("area_ids", encoded)
  end
end

function aardwolf_map.settings.completed_source_hash()
  return aardwolf_map.settings.get_map_value("completed_source_sha256")
end

function aardwolf_map.settings.mark_completed(source_hash)
  aardwolf_map.settings.set_map_value("completed_source_sha256", source_hash)
  aardwolf_map.settings.set_map_value("source_format", aardwolf_map.state.owner_value())
end

function aardwolf_map.settings.record_source_metadata(data)
  local source = aardwolf_map.state.encode_value(data.source)
  local environments = aardwolf_map.state.encode_value(data.environments)
  if source then
    aardwolf_map.settings.set_map_value("source", source)
  end
  if environments then
    aardwolf_map.settings.set_map_value("source_environments", environments)
  end
end

aardwolf_map = aardwolf_map or {}
aardwolf_map.commands = aardwolf_map.commands or {}

function aardwolf_map.commands.start_import()
  aardwolf_map.lifecycle.begin_import()
end

function aardwolf_map.commands.cancel_import()
  aardwolf_map.lifecycle.cancel_import()
end

function aardwolf_map.commands.show_status()
  aardwolf_map.lifecycle.show_status()
end

aardwolf_map = aardwolf_map or {}
aardwolf_map.ui = aardwolf_map.ui or {}

function aardwolf_map.ui.message(message)
  echo("\n[Aardwolf Map] " .. tostring(message) .. "\n")
end

function aardwolf_map.ui.import_started(total_rooms, total_exits)
  aardwolf_map.ui.message("Import started: " .. tostring(total_rooms) .. " rooms and " .. tostring(total_exits) .. " exits will merge in batches.")
end

function aardwolf_map.ui.import_finished(status)
  aardwolf_map.ui.message("Import complete. Created " .. tostring(status.created_rooms) .. " rooms, reused " .. tostring(status.reused_rooms) .. ", and skipped " .. tostring(status.skipped_rooms) .. " protected collisions. Imported " .. tostring(status.imported_exits) .. " exits; skipped " .. tostring(status.skipped_exits) .. ".")
end

function aardwolf_map.ui.status(status)
  local phase = status.phase or "idle"
  aardwolf_map.ui.message("Status: " .. phase .. "; rooms " .. tostring(status.room_index or 0) .. "/" .. tostring(status.room_total or 0) .. ", exits " .. tostring(status.exit_index or 0) .. "/" .. tostring(status.exit_total or 0) .. ".")
end

aardwolf_map = aardwolf_map or {}
aardwolf_map.help = aardwolf_map.help or {}

function aardwolf_map.help.summary()
  return "Commands: aard map import, aard map import cancel, and aard map status."
end
